CREATE TABLE IF NOT EXISTS "users" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Login identity and the address every trade confirmation goes to.
	"email" VARCHAR(320) NOT NULL UNIQUE,
	-- Name as it appears on identity documents. Regulators require the account to match it exactly.
	"legal_name" VARCHAR(200) NOT NULL,
	-- Required before any account can be opened; age gates several product types.
	"date_of_birth" DATE NOT NULL,
	-- Last four of the national tax identifier. The full value lives in the identity vault, not here.
	"tax_id_last_four" CHAR(4),
	-- ISO 3166-1 alpha-2 residence. Drives withholding rates and which instruments are offered.
	"country_code" CHAR(2) NOT NULL,
	-- pending | verified | rejected | review. No order can be accepted until this is verified.
	"kyc_status" VARCHAR(16) NOT NULL DEFAULT 'pending',
	-- Signup time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Soft close. Trade records outlive the relationship by a statutory retention period, so rows are never deleted.
	"closed_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "users" IS 'The natural person behind one or more accounts. Split from accounts because a single customer commonly holds an individual account and a retirement account with different tax treatment.';
COMMENT ON COLUMN "users"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "users"."email" IS 'Login identity and the address every trade confirmation goes to.';
COMMENT ON COLUMN "users"."legal_name" IS 'Name as it appears on identity documents. Regulators require the account to match it exactly.';
COMMENT ON COLUMN "users"."date_of_birth" IS 'Required before any account can be opened; age gates several product types.';
COMMENT ON COLUMN "users"."tax_id_last_four" IS 'Last four of the national tax identifier. The full value lives in the identity vault, not here.';
COMMENT ON COLUMN "users"."country_code" IS 'ISO 3166-1 alpha-2 residence. Drives withholding rates and which instruments are offered.';
COMMENT ON COLUMN "users"."kyc_status" IS 'pending | verified | rejected | review. No order can be accepted until this is verified.';
COMMENT ON COLUMN "users"."created_at" IS 'Signup time.';
COMMENT ON COLUMN "users"."closed_at" IS 'Soft close. Trade records outlive the relationship by a statutory retention period, so rows are never deleted.';

CREATE TABLE IF NOT EXISTS "accounts" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Account owner.
	"user_id" BIGINT NOT NULL,
	-- Number quoted on statements and to the clearing firm. Never reused.
	"account_number" VARCHAR(20) NOT NULL UNIQUE,
	-- cash | margin | ira_traditional | ira_roth. Decides settlement rules and whether unsettled funds can be traded.
	"account_type" VARCHAR(16) NOT NULL,
	-- ISO 4217 base currency. All cash columns on this row are in its minor units.
	"currency_code" CHAR(3) NOT NULL DEFAULT 'USD',
	-- active | restricted | closed. Restricted can close positions but not open them.
	"status" VARCHAR(16) NOT NULL DEFAULT 'active',
	-- Cash that has cleared settlement and can be withdrawn, in minor units.
	"settled_cash_minor" BIGINT NOT NULL DEFAULT 0,
	-- Proceeds from sales that have not reached their settlement date. Spendable on new trades in a margin account, not withdrawable in any account.
	"unsettled_cash_minor" BIGINT NOT NULL DEFAULT 0,
	-- Cached figure the order screen checks, derived from settled cash, margin and open orders. A cache on purpose: recomputing it from the ledger on every keystroke would be the hottest query in the system.
	"buying_power_minor" BIGINT NOT NULL DEFAULT 0,
	-- Set once the day-trade count crosses the regulatory threshold, which raises the minimum equity requirement.
	"pattern_day_trader" BOOLEAN NOT NULL DEFAULT false,
	-- Account opening date.
	"opened_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Closure date. A closed account must hold no positions and zero cash.
	"closed_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "accounts" IS 'One account is one pool of cash and positions under one tax treatment. Keeping the cash columns split between settled and unsettled is what makes the good-faith violation rules expressible at all.';
COMMENT ON COLUMN "accounts"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "accounts"."user_id" IS 'Account owner.';
COMMENT ON COLUMN "accounts"."account_number" IS 'Number quoted on statements and to the clearing firm. Never reused.';
COMMENT ON COLUMN "accounts"."account_type" IS 'cash | margin | ira_traditional | ira_roth. Decides settlement rules and whether unsettled funds can be traded.';
COMMENT ON COLUMN "accounts"."currency_code" IS 'ISO 4217 base currency. All cash columns on this row are in its minor units.';
COMMENT ON COLUMN "accounts"."status" IS 'active | restricted | closed. Restricted can close positions but not open them.';
COMMENT ON COLUMN "accounts"."settled_cash_minor" IS 'Cash that has cleared settlement and can be withdrawn, in minor units.';
COMMENT ON COLUMN "accounts"."unsettled_cash_minor" IS 'Proceeds from sales that have not reached their settlement date. Spendable on new trades in a margin account, not withdrawable in any account.';
COMMENT ON COLUMN "accounts"."buying_power_minor" IS 'Cached figure the order screen checks, derived from settled cash, margin and open orders. A cache on purpose: recomputing it from the ledger on every keystroke would be the hottest query in the system.';
COMMENT ON COLUMN "accounts"."pattern_day_trader" IS 'Set once the day-trade count crosses the regulatory threshold, which raises the minimum equity requirement.';
COMMENT ON COLUMN "accounts"."opened_at" IS 'Account opening date.';
COMMENT ON COLUMN "accounts"."closed_at" IS 'Closure date. A closed account must hold no positions and zero cash.';

CREATE INDEX "idx_accounts_user_type"
ON "accounts" ("user_id", "account_type");

CREATE TABLE IF NOT EXISTS "instruments" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Ticker. Not unique on its own: the same symbol trades on different exchanges and gets reassigned after a delisting.
	"symbol" VARCHAR(16) NOT NULL,
	-- ISO 10383 market identifier. Together with the symbol it identifies the listing.
	"exchange_mic" CHAR(4) NOT NULL,
	-- Issuer name shown in search results.
	"name" VARCHAR(200) NOT NULL,
	-- equity | etf | adr | crypto. Type drives settlement period, trading hours and fee treatment.
	"instrument_type" VARCHAR(16) NOT NULL DEFAULT 'equity',
	-- Currency the instrument trades in.
	"currency_code" CHAR(3) NOT NULL,
	-- False for halted, delisted or restricted names. Positions in an untradable instrument still exist and still need valuing.
	"is_tradable" BOOLEAN NOT NULL DEFAULT true,
	-- Whether the broker will break a share. This is why quantities are decimal throughout rather than integer.
	"fractional_enabled" BOOLEAN NOT NULL DEFAULT false,
	-- Minimum price increment in millionths of a currency unit. A limit price that is not a multiple of it is rejected by the venue.
	"tick_size_micros" BIGINT NOT NULL DEFAULT 10000,
	-- First trading day.
	"listed_on" DATE,
	-- Last trading day. Set rather than deleting the row, because holders still have history and possibly a cash-out to process.
	"delisted_on" DATE,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "instruments" IS 'A tradable listing. Symbols are recycled by exchanges, so the unique key is symbol plus venue and every other table points at this id rather than at a ticker string.';
COMMENT ON COLUMN "instruments"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "instruments"."symbol" IS 'Ticker. Not unique on its own: the same symbol trades on different exchanges and gets reassigned after a delisting.';
COMMENT ON COLUMN "instruments"."exchange_mic" IS 'ISO 10383 market identifier. Together with the symbol it identifies the listing.';
COMMENT ON COLUMN "instruments"."name" IS 'Issuer name shown in search results.';
COMMENT ON COLUMN "instruments"."instrument_type" IS 'equity | etf | adr | crypto. Type drives settlement period, trading hours and fee treatment.';
COMMENT ON COLUMN "instruments"."currency_code" IS 'Currency the instrument trades in.';
COMMENT ON COLUMN "instruments"."is_tradable" IS 'False for halted, delisted or restricted names. Positions in an untradable instrument still exist and still need valuing.';
COMMENT ON COLUMN "instruments"."fractional_enabled" IS 'Whether the broker will break a share. This is why quantities are decimal throughout rather than integer.';
COMMENT ON COLUMN "instruments"."tick_size_micros" IS 'Minimum price increment in millionths of a currency unit. A limit price that is not a multiple of it is rejected by the venue.';
COMMENT ON COLUMN "instruments"."listed_on" IS 'First trading day.';
COMMENT ON COLUMN "instruments"."delisted_on" IS 'Last trading day. Set rather than deleting the row, because holders still have history and possibly a cash-out to process.';

CREATE UNIQUE INDEX "uq_instruments_symbol_exchange"
ON "instruments" ("symbol", "exchange_mic");

CREATE TABLE IF NOT EXISTS "orders" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Account the order is placed for.
	"account_id" BIGINT NOT NULL,
	-- What is being traded.
	"instrument_id" BIGINT NOT NULL,
	-- Idempotency key from the app. A retried submit after a flaky connection must not become two orders.
	"client_order_id" VARCHAR(64) NOT NULL UNIQUE,
	-- Identifier assigned by the execution venue once accepted. Null while the order is still local.
	"venue_order_id" VARCHAR(64),
	-- buy | sell.
	"side" VARCHAR(4) NOT NULL,
	-- market | limit | stop | stop_limit. The type decides which of the two price columns must be set.
	"order_type" VARCHAR(12) NOT NULL,
	-- day | gtc | ioc | fok | gtd. Day orders die at the close; gtc rests for weeks, which is why expires_at exists as a hard backstop.
	"time_in_force" VARCHAR(8) NOT NULL DEFAULT 'day',
	-- Share quantity requested. Decimal because fractional shares are real; null for a notional order where the customer asked for an amount of money instead.
	"quantity" DECIMAL(18,8),
	-- Amount of money to spend, in minor units, for a dollar-based order. Exactly one of quantity and notional_minor is set.
	"notional_minor" BIGINT,
	-- Limit price in millionths of a currency unit. Required for limit and stop_limit orders, null otherwise.
	"limit_price_micros" BIGINT,
	-- Trigger price in millionths. Required for stop and stop_limit orders. Stored separately from the limit price because a stop_limit needs both.
	"stop_price_micros" BIGINT,
	-- Sum of execution quantities. Maintained alongside the fills so the open portion can be cancelled without aggregating.
	"filled_quantity" DECIMAL(18,8) NOT NULL DEFAULT 0,
	-- Quantity-weighted average of the fills. Null until the first execution lands.
	"average_fill_price_micros" BIGINT,
	-- pending | accepted | partially_filled | filled | canceled | rejected | expired. Partially_filled is a resting state, not a transient one.
	"status" VARCHAR(16) NOT NULL DEFAULT 'pending',
	-- Why the venue or the risk check refused it. Null on a healthy order.
	"reject_reason" VARCHAR(120),
	-- Whether the order may execute outside regular hours, where spreads are wider and the customer had to opt in.
	"extended_hours" BOOLEAN NOT NULL DEFAULT false,
	-- When the customer pressed the button.
	"submitted_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- When a gtd or gtc order lapses.
	"expires_at" TIMESTAMPTZ,
	-- When the cancel was confirmed by the venue, which is later than when it was requested.
	"canceled_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "orders" IS 'The customer instruction, kept separate from what actually happened to it. An order is a request that may be filled once, in twenty pieces, or never; the columns here are intent plus a running summary of the fills.';
COMMENT ON COLUMN "orders"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "orders"."account_id" IS 'Account the order is placed for.';
COMMENT ON COLUMN "orders"."instrument_id" IS 'What is being traded.';
COMMENT ON COLUMN "orders"."client_order_id" IS 'Idempotency key from the app. A retried submit after a flaky connection must not become two orders.';
COMMENT ON COLUMN "orders"."venue_order_id" IS 'Identifier assigned by the execution venue once accepted. Null while the order is still local.';
COMMENT ON COLUMN "orders"."side" IS 'buy | sell.';
COMMENT ON COLUMN "orders"."order_type" IS 'market | limit | stop | stop_limit. The type decides which of the two price columns must be set.';
COMMENT ON COLUMN "orders"."time_in_force" IS 'day | gtc | ioc | fok | gtd. Day orders die at the close; gtc rests for weeks, which is why expires_at exists as a hard backstop.';
COMMENT ON COLUMN "orders"."quantity" IS 'Share quantity requested. Decimal because fractional shares are real; null for a notional order where the customer asked for an amount of money instead.';
COMMENT ON COLUMN "orders"."notional_minor" IS 'Amount of money to spend, in minor units, for a dollar-based order. Exactly one of quantity and notional_minor is set.';
COMMENT ON COLUMN "orders"."limit_price_micros" IS 'Limit price in millionths of a currency unit. Required for limit and stop_limit orders, null otherwise.';
COMMENT ON COLUMN "orders"."stop_price_micros" IS 'Trigger price in millionths. Required for stop and stop_limit orders. Stored separately from the limit price because a stop_limit needs both.';
COMMENT ON COLUMN "orders"."filled_quantity" IS 'Sum of execution quantities. Maintained alongside the fills so the open portion can be cancelled without aggregating.';
COMMENT ON COLUMN "orders"."average_fill_price_micros" IS 'Quantity-weighted average of the fills. Null until the first execution lands.';
COMMENT ON COLUMN "orders"."status" IS 'pending | accepted | partially_filled | filled | canceled | rejected | expired. Partially_filled is a resting state, not a transient one.';
COMMENT ON COLUMN "orders"."reject_reason" IS 'Why the venue or the risk check refused it. Null on a healthy order.';
COMMENT ON COLUMN "orders"."extended_hours" IS 'Whether the order may execute outside regular hours, where spreads are wider and the customer had to opt in.';
COMMENT ON COLUMN "orders"."submitted_at" IS 'When the customer pressed the button.';
COMMENT ON COLUMN "orders"."expires_at" IS 'When a gtd or gtc order lapses.';
COMMENT ON COLUMN "orders"."canceled_at" IS 'When the cancel was confirmed by the venue, which is later than when it was requested.';

CREATE INDEX "idx_orders_account_submitted"
ON "orders" ("account_id", "submitted_at");
CREATE INDEX "idx_orders_instrument_status"
ON "orders" ("instrument_id", "status");

CREATE TABLE IF NOT EXISTS "executions" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Parent order. One order routinely produces several executions at different prices.
	"order_id" BIGINT NOT NULL,
	-- Venue execution id. Unique so a replayed drop copy cannot book the same fill twice, which would corrupt both the position and the cash.
	"execution_reference" VARCHAR(64) NOT NULL UNIQUE,
	-- Shares filled by this execution, always positive. The side comes from the order.
	"quantity" DECIMAL(18,8) NOT NULL,
	-- Execution price in millionths of a currency unit. Integer at a finer scale than cents because sub-cent price improvement is genuine and a float price will not reconcile against the venue report.
	"price_micros" BIGINT NOT NULL,
	-- quantity times price, rounded to minor units once, here. Every downstream figure uses this rounded value so the books cannot drift by fractions of a cent.
	"gross_amount_minor" BIGINT NOT NULL,
	-- Regulatory and venue fees for this fill, in minor units. Charged per execution, which is why it cannot live on the order.
	"fee_minor" BIGINT NOT NULL DEFAULT 0,
	-- Where it executed. Retail order flow is routed, and the venue must be disclosed.
	"venue" VARCHAR(24) NOT NULL,
	-- maker | taker. Drives rebates and is part of best-execution reporting.
	"liquidity_flag" VARCHAR(8),
	-- Local trading day. A fill at 21:05 belongs to the next trading day, which is why this is a stored date and not a cast of the timestamp.
	"trade_date" DATE NOT NULL,
	-- Trade date plus the instrument settlement cycle. Computed once against the exchange holiday calendar, because recomputing it later would need that calendar as it was on the day.
	"settlement_date" DATE NOT NULL,
	-- Exact venue timestamp, to the microsecond, used for sequencing and for dispute resolution.
	"executed_at" TIMESTAMPTZ NOT NULL,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "executions" IS 'The immutable record of a trade actually happening. Executions are the source of truth for positions, cash and tax lots; everything else in this schema that looks like a balance is derived from this table.';
COMMENT ON COLUMN "executions"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "executions"."order_id" IS 'Parent order. One order routinely produces several executions at different prices.';
COMMENT ON COLUMN "executions"."execution_reference" IS 'Venue execution id. Unique so a replayed drop copy cannot book the same fill twice, which would corrupt both the position and the cash.';
COMMENT ON COLUMN "executions"."quantity" IS 'Shares filled by this execution, always positive. The side comes from the order.';
COMMENT ON COLUMN "executions"."price_micros" IS 'Execution price in millionths of a currency unit. Integer at a finer scale than cents because sub-cent price improvement is genuine and a float price will not reconcile against the venue report.';
COMMENT ON COLUMN "executions"."gross_amount_minor" IS 'quantity times price, rounded to minor units once, here. Every downstream figure uses this rounded value so the books cannot drift by fractions of a cent.';
COMMENT ON COLUMN "executions"."fee_minor" IS 'Regulatory and venue fees for this fill, in minor units. Charged per execution, which is why it cannot live on the order.';
COMMENT ON COLUMN "executions"."venue" IS 'Where it executed. Retail order flow is routed, and the venue must be disclosed.';
COMMENT ON COLUMN "executions"."liquidity_flag" IS 'maker | taker. Drives rebates and is part of best-execution reporting.';
COMMENT ON COLUMN "executions"."trade_date" IS 'Local trading day. A fill at 21:05 belongs to the next trading day, which is why this is a stored date and not a cast of the timestamp.';
COMMENT ON COLUMN "executions"."settlement_date" IS 'Trade date plus the instrument settlement cycle. Computed once against the exchange holiday calendar, because recomputing it later would need that calendar as it was on the day.';
COMMENT ON COLUMN "executions"."executed_at" IS 'Exact venue timestamp, to the microsecond, used for sequencing and for dispute resolution.';

CREATE INDEX "idx_executions_order"
ON "executions" ("order_id");
CREATE INDEX "idx_executions_dates"
ON "executions" ("trade_date", "settlement_date");

CREATE TABLE IF NOT EXISTS "positions" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Holding account.
	"account_id" BIGINT NOT NULL,
	-- Instrument held.
	"instrument_id" BIGINT NOT NULL,
	-- Net shares held, buys minus sells. Negative in a margin account that is short.
	"quantity" DECIMAL(18,8) NOT NULL DEFAULT 0,
	-- Weighted average cost per share in millionths, recomputed on every buy and left unchanged by sells. Null when the quantity is zero.
	"average_cost_micros" BIGINT,
	-- Book cost of the current holding in minor units. Kept alongside the average so unrealised profit is a subtraction rather than a multiplication that re-rounds.
	"total_cost_minor" BIGINT NOT NULL DEFAULT 0,
	-- Running realised profit from closed quantity. Accumulated on each sell, because the alternative is replaying every fill ever to draw one screen.
	"realized_pnl_minor" BIGINT NOT NULL DEFAULT 0,
	-- When the position first went non-zero.
	"opened_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Timestamp of the most recent execution folded in. This is the watermark a rebuild compares against to prove the row is current.
	"last_fill_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "positions" IS 'A derived projection of the executions for one account and instrument, not an independent fact. It exists because every app screen needs it and folding thousands of fills on each request is untenable; it must always be reproducible by replaying executions in order.';
COMMENT ON COLUMN "positions"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "positions"."account_id" IS 'Holding account.';
COMMENT ON COLUMN "positions"."instrument_id" IS 'Instrument held.';
COMMENT ON COLUMN "positions"."quantity" IS 'Net shares held, buys minus sells. Negative in a margin account that is short.';
COMMENT ON COLUMN "positions"."average_cost_micros" IS 'Weighted average cost per share in millionths, recomputed on every buy and left unchanged by sells. Null when the quantity is zero.';
COMMENT ON COLUMN "positions"."total_cost_minor" IS 'Book cost of the current holding in minor units. Kept alongside the average so unrealised profit is a subtraction rather than a multiplication that re-rounds.';
COMMENT ON COLUMN "positions"."realized_pnl_minor" IS 'Running realised profit from closed quantity. Accumulated on each sell, because the alternative is replaying every fill ever to draw one screen.';
COMMENT ON COLUMN "positions"."opened_at" IS 'When the position first went non-zero.';
COMMENT ON COLUMN "positions"."last_fill_at" IS 'Timestamp of the most recent execution folded in. This is the watermark a rebuild compares against to prove the row is current.';

CREATE UNIQUE INDEX "uq_positions_account_instrument"
ON "positions" ("account_id", "instrument_id");

CREATE TABLE IF NOT EXISTS "cash_movements" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Account whose cash moves.
	"account_id" BIGINT NOT NULL,
	-- deposit | withdrawal | trade_buy | trade_sell | dividend | fee | interest | adjustment.
	"movement_type" VARCHAR(20) NOT NULL,
	-- Source fill, when the movement is the cash leg of a trade.
	"execution_id" BIGINT,
	-- Source dividend, when the movement is a distribution.
	"dividend_payment_id" BIGINT,
	-- Signed amount in minor units. Negative leaves the account. Integer only: a brokerage that rounds cash in floating point fails its first reconciliation.
	"amount_minor" BIGINT NOT NULL,
	-- ISO 4217, matching the account base currency.
	"currency_code" CHAR(3) NOT NULL,
	-- Day the movement was initiated.
	"trade_date" DATE NOT NULL,
	-- Day the cash becomes withdrawable. The gap between these two dates is the entire reason unsettled cash is tracked separately.
	"settlement_date" DATE NOT NULL,
	-- pending | settled | reversed. A reversal appends a mirrored row rather than editing this one.
	"status" VARCHAR(16) NOT NULL DEFAULT 'pending',
	-- Statement narrative, snapshotted so a later symbol change does not rewrite an old statement line.
	"description" VARCHAR(200),
	-- Write time. The table is append-only.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "cash_movements" IS 'The append-only cash journal. The settled and unsettled columns on accounts are sums over this table split by settlement_date against today, which is how a T plus one regime is enforced without a nightly batch rewriting balances.';
COMMENT ON COLUMN "cash_movements"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "cash_movements"."account_id" IS 'Account whose cash moves.';
COMMENT ON COLUMN "cash_movements"."movement_type" IS 'deposit | withdrawal | trade_buy | trade_sell | dividend | fee | interest | adjustment.';
COMMENT ON COLUMN "cash_movements"."execution_id" IS 'Source fill, when the movement is the cash leg of a trade.';
COMMENT ON COLUMN "cash_movements"."dividend_payment_id" IS 'Source dividend, when the movement is a distribution.';
COMMENT ON COLUMN "cash_movements"."amount_minor" IS 'Signed amount in minor units. Negative leaves the account. Integer only: a brokerage that rounds cash in floating point fails its first reconciliation.';
COMMENT ON COLUMN "cash_movements"."currency_code" IS 'ISO 4217, matching the account base currency.';
COMMENT ON COLUMN "cash_movements"."trade_date" IS 'Day the movement was initiated.';
COMMENT ON COLUMN "cash_movements"."settlement_date" IS 'Day the cash becomes withdrawable. The gap between these two dates is the entire reason unsettled cash is tracked separately.';
COMMENT ON COLUMN "cash_movements"."status" IS 'pending | settled | reversed. A reversal appends a mirrored row rather than editing this one.';
COMMENT ON COLUMN "cash_movements"."description" IS 'Statement narrative, snapshotted so a later symbol change does not rewrite an old statement line.';
COMMENT ON COLUMN "cash_movements"."created_at" IS 'Write time. The table is append-only.';

CREATE INDEX "idx_cash_account_settlement"
ON "cash_movements" ("account_id", "settlement_date");
CREATE INDEX "idx_cash_account_created"
ON "cash_movements" ("account_id", "created_at");

CREATE TABLE IF NOT EXISTS "dividends" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Instrument making the distribution.
	"instrument_id" BIGINT NOT NULL,
	-- cash | special | stock | return_of_capital. Each has different tax treatment, so the type must survive on the row.
	"dividend_type" VARCHAR(24) NOT NULL DEFAULT 'cash',
	-- Declared amount per share in millionths. Per share rather than per account, because the same declaration pays every holder.
	"amount_per_share_micros" BIGINT NOT NULL,
	-- Currency declared in, which is not always the account currency.
	"currency_code" CHAR(3) NOT NULL,
	-- When the issuer announced it.
	"declared_date" DATE NOT NULL,
	-- First day the shares trade without the dividend. Buying on this date does not earn it, which is the rule that surprises customers most.
	"ex_date" DATE NOT NULL,
	-- Ownership snapshot date. Entitlement is decided by what positions looked like at this close, not today.
	"record_date" DATE NOT NULL,
	-- When cash actually reaches accounts, often weeks after the record date.
	"payable_date" DATE NOT NULL,
	-- When the corporate action was ingested.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "dividends" IS 'The issuer-level declaration, stored once. Holding four dates rather than one is what makes entitlement calculable after the fact, because the answer depends on positions at the record date and not on when the job happened to run.';
COMMENT ON COLUMN "dividends"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "dividends"."instrument_id" IS 'Instrument making the distribution.';
COMMENT ON COLUMN "dividends"."dividend_type" IS 'cash | special | stock | return_of_capital. Each has different tax treatment, so the type must survive on the row.';
COMMENT ON COLUMN "dividends"."amount_per_share_micros" IS 'Declared amount per share in millionths. Per share rather than per account, because the same declaration pays every holder.';
COMMENT ON COLUMN "dividends"."currency_code" IS 'Currency declared in, which is not always the account currency.';
COMMENT ON COLUMN "dividends"."declared_date" IS 'When the issuer announced it.';
COMMENT ON COLUMN "dividends"."ex_date" IS 'First day the shares trade without the dividend. Buying on this date does not earn it, which is the rule that surprises customers most.';
COMMENT ON COLUMN "dividends"."record_date" IS 'Ownership snapshot date. Entitlement is decided by what positions looked like at this close, not today.';
COMMENT ON COLUMN "dividends"."payable_date" IS 'When cash actually reaches accounts, often weeks after the record date.';
COMMENT ON COLUMN "dividends"."created_at" IS 'When the corporate action was ingested.';

CREATE UNIQUE INDEX "uq_dividends_instrument_exdate"
ON "dividends" ("instrument_id", "ex_date");

CREATE TABLE IF NOT EXISTS "dividend_payments" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Declaration being paid.
	"dividend_id" BIGINT NOT NULL,
	-- Account receiving it.
	"account_id" BIGINT NOT NULL,
	-- Shares held at the record date close, snapshotted. The current position is irrelevant and usually different, which is why this cannot be a join.
	"entitled_quantity" DECIMAL(18,8) NOT NULL,
	-- Entitled quantity times the per-share rate, rounded once to minor units.
	"gross_amount_minor" BIGINT NOT NULL,
	-- Tax withheld at source, driven by the holder residence country. Stored so the year-end tax form is a sum rather than a recomputation against rules that have since changed.
	"withholding_minor" BIGINT NOT NULL DEFAULT 0,
	-- Gross less withholding. This is the figure that appears in the cash journal.
	"net_amount_minor" BIGINT NOT NULL,
	-- pending | paid | reversed. Reversals happen when an issuer restates a distribution.
	"status" VARCHAR(16) NOT NULL DEFAULT 'pending',
	-- Whether the net amount bought more shares instead of settling as cash, which produces an order rather than a cash movement.
	"reinvested" BOOLEAN NOT NULL DEFAULT false,
	-- When the payment posted. Null until the payable date.
	"paid_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "dividend_payments" IS 'One row per holder per declaration. The unique key is the idempotency guarantee for the payment job: rerunning it after a crash cannot pay anyone twice.';
COMMENT ON COLUMN "dividend_payments"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "dividend_payments"."dividend_id" IS 'Declaration being paid.';
COMMENT ON COLUMN "dividend_payments"."account_id" IS 'Account receiving it.';
COMMENT ON COLUMN "dividend_payments"."entitled_quantity" IS 'Shares held at the record date close, snapshotted. The current position is irrelevant and usually different, which is why this cannot be a join.';
COMMENT ON COLUMN "dividend_payments"."gross_amount_minor" IS 'Entitled quantity times the per-share rate, rounded once to minor units.';
COMMENT ON COLUMN "dividend_payments"."withholding_minor" IS 'Tax withheld at source, driven by the holder residence country. Stored so the year-end tax form is a sum rather than a recomputation against rules that have since changed.';
COMMENT ON COLUMN "dividend_payments"."net_amount_minor" IS 'Gross less withholding. This is the figure that appears in the cash journal.';
COMMENT ON COLUMN "dividend_payments"."status" IS 'pending | paid | reversed. Reversals happen when an issuer restates a distribution.';
COMMENT ON COLUMN "dividend_payments"."reinvested" IS 'Whether the net amount bought more shares instead of settling as cash, which produces an order rather than a cash movement.';
COMMENT ON COLUMN "dividend_payments"."paid_at" IS 'When the payment posted. Null until the payable date.';

CREATE UNIQUE INDEX "uq_dividend_payments_dividend_account"
ON "dividend_payments" ("dividend_id", "account_id");

CREATE TABLE IF NOT EXISTS "watchlists" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owner. Watchlists follow the person, not the account, because the same names are watched across both.
	"user_id" BIGINT NOT NULL,
	-- List name chosen by the user.
	"name" VARCHAR(80) NOT NULL,
	-- The list shown on opening the app. Exactly one per user.
	"is_default" BOOLEAN NOT NULL DEFAULT false,
	-- Order of the lists themselves in the sidebar.
	"display_order" SMALLINT NOT NULL DEFAULT 0,
	-- Creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "watchlists" IS 'A named collection of instruments. Attached to the user rather than the account so a customer with an individual and a retirement account does not see their lists duplicated.';
COMMENT ON COLUMN "watchlists"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "watchlists"."user_id" IS 'Owner. Watchlists follow the person, not the account, because the same names are watched across both.';
COMMENT ON COLUMN "watchlists"."name" IS 'List name chosen by the user.';
COMMENT ON COLUMN "watchlists"."is_default" IS 'The list shown on opening the app. Exactly one per user.';
COMMENT ON COLUMN "watchlists"."display_order" IS 'Order of the lists themselves in the sidebar.';
COMMENT ON COLUMN "watchlists"."created_at" IS 'Creation time.';

CREATE UNIQUE INDEX "uq_watchlists_user_name"
ON "watchlists" ("user_id", "name");

CREATE TABLE IF NOT EXISTS "watchlist_items" (
	-- Parent list. Half of the composite primary key.
	"watchlist_id" BIGINT,
	-- Instrument watched. The composite key makes adding the same symbol twice a no-op instead of a duplicate row.
	"instrument_id" BIGINT,
	-- Manual position within the list, since users reorder by dragging.
	"display_order" SMALLINT NOT NULL DEFAULT 0,
	-- When it was added, used for the recently-added sort.
	"added_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("watchlist_id", "instrument_id")
);

COMMENT ON TABLE "watchlist_items" IS 'A join table with no surrogate id. The pair is the identity, so uniqueness comes from the primary key rather than an extra constraint that could be forgotten.';
COMMENT ON COLUMN "watchlist_items"."watchlist_id" IS 'Parent list. Half of the composite primary key.';
COMMENT ON COLUMN "watchlist_items"."instrument_id" IS 'Instrument watched. The composite key makes adding the same symbol twice a no-op instead of a duplicate row.';
COMMENT ON COLUMN "watchlist_items"."display_order" IS 'Manual position within the list, since users reorder by dragging.';
COMMENT ON COLUMN "watchlist_items"."added_at" IS 'When it was added, used for the recently-added sort.';

CREATE INDEX "idx_watchlist_items_order"
ON "watchlist_items" ("watchlist_id", "display_order");

CREATE TABLE IF NOT EXISTS "price_alerts" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Who gets notified.
	"user_id" BIGINT NOT NULL,
	-- Instrument being watched.
	"instrument_id" BIGINT NOT NULL,
	-- above | below. Stored rather than inferred from the current price, because the current price at creation time is not what the user meant.
	"direction" VARCHAR(8) NOT NULL,
	-- Trigger level in millionths of a currency unit, on the same scale as execution prices so a comparison never needs conversion.
	"threshold_price_micros" BIGINT NOT NULL,
	-- active | triggered | expired | canceled. A triggered alert stays as a row so the user can see why they were notified.
	"status" VARCHAR(12) NOT NULL DEFAULT 'active',
	-- Price that actually crossed the threshold, which is rarely exactly the threshold.
	"triggered_price_micros" BIGINT,
	-- When it fired.
	"triggered_at" TIMESTAMPTZ,
	-- Optional lapse time, so abandoned alerts stop consuming evaluation work forever.
	"expires_at" TIMESTAMPTZ,
	-- Creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "price_alerts" IS 'A standing condition evaluated against the market feed. Indexed by instrument first because the evaluation loop walks a price tick and asks which alerts care, never the other way round.';
COMMENT ON COLUMN "price_alerts"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "price_alerts"."user_id" IS 'Who gets notified.';
COMMENT ON COLUMN "price_alerts"."instrument_id" IS 'Instrument being watched.';
COMMENT ON COLUMN "price_alerts"."direction" IS 'above | below. Stored rather than inferred from the current price, because the current price at creation time is not what the user meant.';
COMMENT ON COLUMN "price_alerts"."threshold_price_micros" IS 'Trigger level in millionths of a currency unit, on the same scale as execution prices so a comparison never needs conversion.';
COMMENT ON COLUMN "price_alerts"."status" IS 'active | triggered | expired | canceled. A triggered alert stays as a row so the user can see why they were notified.';
COMMENT ON COLUMN "price_alerts"."triggered_price_micros" IS 'Price that actually crossed the threshold, which is rarely exactly the threshold.';
COMMENT ON COLUMN "price_alerts"."triggered_at" IS 'When it fired.';
COMMENT ON COLUMN "price_alerts"."expires_at" IS 'Optional lapse time, so abandoned alerts stop consuming evaluation work forever.';
COMMENT ON COLUMN "price_alerts"."created_at" IS 'Creation time.';

CREATE INDEX "idx_alerts_instrument_status"
ON "price_alerts" ("instrument_id", "status");
CREATE INDEX "idx_alerts_user_status"
ON "price_alerts" ("user_id", "status");

